import re

def _parse_num(s):
    if s is None: return None
    s = str(s).strip()
    if s in ('', '—', '-', '–', 'None', 'n/a', 'N/A', 'col0', 'Note'): return None
    neg = False
    if s.startswith('(') and s.endswith(')'):
        neg = True
        s = s[1:-1]
    s = re.sub(r'[^\d.\-]', '', s)
    if not s or s == '-': return None
    try:
        v = float(s)
        return -v if neg else v
    except ValueError:
        return None

def _get_time(col_str):
    if not col_str: return None
    s = str(col_str)
    m = re.search(r'\b((?:19|20)\d{2})\b', s)
    if m: return float(m.group(1))
    m = re.search(r'\b[Ff](\d{2})\b', s)
    if m: return float(2000 + int(m.group(1)))
    return None

def _is_section_header(rd, label_col):
    val = (rd.get(label_col) or '').strip()
    if not val: return True
    vl = val.lower()
    if vl.startswith('(') or vl.startswith('note') or 'in ' in vl[:5] or 'year' in vl or 'fiscal' in vl or 'quarter' in vl or 'period' in vl:
        return True
    if re.match(r'^\s*\(\$?|\(in|\(dollars|\(m|\(£|\(€|\(nt|\(millions|\(thousands', vl):
        return True
    return False

def entities(doc, scope):
    nodes = scope_nodes(doc, scope)
    ent_set = set()
    for n in nodes:
        if n.get('kind') == 'table':
            cols = n['table']['columns']
            if not cols: continue
            label_col = cols[0]
            for idx, rd in table_rows(n):
                name = (rd.get(label_col) or '').strip()
                if not name: continue
                if _is_section_header(rd, label_col): continue
                ent_set.add(name)
    return [{"id": e, "description": e} for e in sorted(ent_set)]

def recorded_end(doc, scope):
    nodes = scope_nodes(doc, scope)
    max_t = None
    for n in nodes:
        if n.get('kind') == 'table':
            for c in n['table']['columns']:
                t = _get_time(c)
                if t is not None and (max_t is None or t > max_t):
                    max_t = t
        elif n.get('kind') in ('list', 'text'):
            lines = n.get('lines') or [n.get('text', '')]
            for line in lines:
                t = _get_time(line)
                if t is not None and (max_t is None or t > max_t):
                    max_t = t
    return max_t

def inputs(doc, scope):
    return []

def outcomes(doc, scope):
    nodes = scope_nodes(doc, scope)
    outs = []
    for n in nodes:
        if n.get('kind') == 'table':
            cols = n['table']['columns']
            if not cols: continue
            label_col = cols[0]
            for idx, rd in table_rows(n):
                name = (rd.get(label_col) or '').strip()
                if not name or _is_section_header(rd, label_col): continue

                for col in cols:
                    if col == label_col: continue
                    t = _get_time(col)
                    val = _parse_num(rd.get(col, ''))
                    if val is not None:
                        kind = "percentage" if "%" in (col + (rd.get(col,''))) else "financial_figure"
                        outs.append({
                            "time": t,
                            "kind": kind,
                            "entities": [name],
                            "value": val,
                            "src": [[n['node_id'], idx, [label_col, col]]]
                        })
    return outs

def params(doc, scope):
    return {}


# ---- step 2: forward model ----
def simulate(doc, scope, inputs, params, start=None, horizon=None):
    rec_end = recorded_end(doc, scope)
    if horizon is None: horizon = rec_end
    if start is None: start = rec_end

    # Group inputs by time
    time_vals = {}
    for inp in inputs:
        t = inp['time']
        ent = inp['entities'][0]
        val = inp['value']
        time_vals.setdefault(t, {})[ent] = val

    # Filter times to simulation window
    sim_times = sorted([t for t in time_vals.keys() if t > start and t <= horizon])
    results = []

    # Identify the "Total" entity name dynamically
    total_name = None
    all_inp_ents = [inp['entities'][0] for inp in inputs]
    for e in all_inp_ents:
        if e.startswith("Total"):
            total_name = e
            break

    if not total_name:
        scope_ents = [e['id'] for e in entities(doc, scope)]
        for e in scope_ents:
            if e.startswith("Total"):
                total_name = e
                break

    for t in sim_times:
        vals = time_vals[t]
        # Separate components from totals
        comp_vals = {e: v for e, v in vals.items() if not e.startswith("Total")}

        # If components are provided but the total is not, compute it
        if comp_vals and total_name:
            computed_total = sum(comp_vals.values())
            if total_name not in vals:
                vals[total_name] = computed_total

        # Build outcome records for all participating entities at this time
        for ent, v in vals.items():
            results.append({
                "time": t,
                "kind": "financial_figure",
                "entities": [ent],
                "value": v,
                "src": []
            })
    return results

