                "value": inp['value'],
                "src": []
            })

        # Compute totals if components are provided but total is missing
        for total_name in total_names:
            if total_name not in ent_vals:
                # Sum components, excluding other totals or deductions
                total_val = sum(v for e, v in ent_vals.items() 
                               if 'total' not in e.lower() and 'less' not in e.lower() and 'adjustments' not in e.lower())
                if total_val != 0:
                    results.append({
