import numpy as np

def simulate(doc, scope, inputs, params, start=None, horizon=None):
    hist = outcomes(doc, scope)
    times = sorted(set(o['time'] for o in hist))
    if not times: return []

    if horizon is None: horizon = max(times)
    if start is None: start = min(times) - 1.0

    target_times = [t for t in times if start < t <= horizon]
    if not target_times: return []

    ent_data = {}
    for o in hist:
        e = o['entities'][0]
        ent_data.setdefault(e, {})[o['time']] = o['value']

    entities = list(ent_data.keys())
    is_sum = {e: [] for e in entities}

    # Detect sum relationships (Total = sum of components)
    for e in entities:
        for t in times:
            if t not in ent_data[e]: continue
            v = ent_data[e][t]
            if abs(v) < 1e-9: continue
            others = [ent_data[x][t] for x in entities if x != e and t in ent_data[x]]
            if not others: continue
            s = sum(others)
            # Check if value is approximately the sum of others (5% tolerance)
            if abs(s) > 1e-9 and abs(v - s) / max(abs(v), abs(s)) < 0.05:
                is_sum[e] = [x for x in entities if x != e]
                break

    # Topological sort: components before totals
    order = []
    vis = set()
    def dfs(e):
        if e in vis: return
        if is_sum[e]:
            for c in is_sum[e]: dfs(c)
        vis.add(e)
        order.append(e)
    for e in entities: dfs(e)

    preds = {}
    def predict(e):
        if e in preds: return
        if is_sum[e]:
            for c in is_sum[e]: predict(c)
            preds[e] = {t: sum(preds.get(c, {}).get(t, 0.0) for c in is_sum[e]) for t in target_times}
            return

        data = sorted(ent_data[e].items())
        if not data: return
        if len(data) >= 2:
            ts, vs = zip(*data)
            # Linear trend extrapolation/interpolation
            poly = np.poly1d(np.polyfit(ts, vs, 1))
        else:
            val = data[0][1]
            poly = lambda t: val

        preds[e] = {t: poly(t) for t in target_times}

    for e in order: predict(e)

    res = []
    for o in hist:
        if o['time'] in target_times:
            e = o['entities'][0]
            if e in preds and o['time'] in preds[e]:
                new_o = dict(o)
                new_o['value'] = preds[e][o['time']]
                res.append(new_o)
    return res

