import numpy as np

def simulate(doc, scope, inputs, params, start=None, horizon=None):
    hist = outcomes(doc, scope)

    all_times = set()
    src_map = {}
    ent_kinds = {}

    for n in scope_nodes(doc, scope):
        if n['kind'] != 'table': continue
        cols = n['table']['columns']
        if not cols: continue
        label_col = cols[0]

        for idx, row in enumerate(n['table']['rows']):
            row_dict = dict(zip(cols, row))
            name = (row_dict.get(label_col) or '').strip()
            if not name: continue

            for col in cols:
                if col == label_col: continue
                t = _get_time(col)
                if t is not None:
                    all_times.add(t)
                    kind = "percentage" if "%" in str(col + row_dict.get(col, '')) else "financial_figure"
                    if name not in ent_kinds: ent_kinds[name] = set()
                    ent_kinds[name].add(kind)
                    src_map[(name, t)] = [[n['node_id'], idx, [label_col, col]]]

    times = sorted(all_times)
    if not times: return []
    if horizon is None: horizon = max(times)
    if start is None: start = min(times) - 1.0
    target_times = [t for t in times if start < t <= horizon]
    if not target_times: return []

    entities = sorted(ent_kinds.keys())
    if not entities: return []

    # Detect sum relationships from historical data
    is_sum = {e: False for e in entities}
    for e in entities:
        for t in times:
            vals = {o['entities'][0]: o['value'] for o in hist if o['time'] == t and o['value'] is not None}
            if e not in vals: continue
            v = vals[e]
            if abs(v) < 1e-9: continue
            others = [vals[x] for x in vals if x != e]
            if others and abs(sum(others) - v) / max(abs(v), 1e-9) < 0.05:
                is_sum[e] = True
                break

    def predict(e, t):
        # 1. Use provided inputs if available
        for inp in inputs:
            if e in inp['entities'] and inp['time'] == t:
                return inp['value']
        # 2. Use historical recorded values
        for o in hist:
            if o['entities'][0] == e and o['time'] == t:
                return o['value']
        # 3. Compute as sum of components if detected
        if is_sum[e]:
            return sum(predict(c, t) or 0.0 for c in entities if c != e)
        # 4. Extrapolate from trend
        data = [(o['time'], o['value']) for o in hist if o['entities'][0] == e and o['value'] is not None]
        if not data: return 0.0
        data.sort()
        if len(data) == 1: return data[0][1]
        try:
            ts, vs = zip(*data)
            if len(set(ts)) < 2: return data[-1][1]
            p = np.poly1d(np.polyfit(ts, vs, 1))
            return float(p(t))
        except:
            return data[-1][1]

    res = []
    for e in entities:
        for t in target_times:
            val = predict(e, t)
            if val is None: continue
            kind = list(ent_kinds[e])[0] if ent_kinds[e] else "financial_figure"
            src = src_map.get((e, t), [[None, 0, [None, None]]])
            res.append({"time": t, "kind": kind, "entities": [e], "value": val, "src": src})
    return res

