import numpy as np

def simulate(doc, scope, inputs, params, start=None, horizon=None):
    hist = outcomes(doc, scope)

    inp_by_ent = {}
    ent_kind = {}
    for inp in inputs:
        if not inp.get('entities'): continue
        e = inp['entities'][0]
        inp_by_ent.setdefault(e, {})[inp['time']] = inp['value']
        ent_kind[e] = inp.get('kind', 'financial_figure')

    for o in hist:
        e = o['entities'][0]
        ent_kind.setdefault(e, o['kind'])
        if e not in inp_by_ent:
            inp_by_ent[e] = {}

    entities = list(inp_by_ent.keys())
    if not entities:
        entities = list(set(o['entities'][0] for o in hist))
    if not entities:
        return []

    times = set()
    try:
        for n in scope_nodes(doc, scope):
            if n.get('kind') == 'table' and n.get('table', {}).get('columns'):
                cols = n['table']['columns']
                if len(cols) > 1:
                    has_time = False
                    for c in cols[1:]:
                        t = _get_time(c)
                        if t is not None:
                            times.add(t)
                            has_time = True
                    if not has_time:
                        times.add(None)
    except:
        pass

    times.update(inp['time'] for inp in inputs)
    times.update(o['time'] for o in hist)

    num_times = [t for t in times if t is not None]
    if start is not None:
        num_times = [t for t in num_times if t > start]
    if horizon is not None:
        num_times = [t for t in num_times if t <= horizon]
    num_times.sort()
    target_times = num_times
    if None in times and start is None:
        target_times.insert(0, None)

    res = []
    for e in entities:
        kind = ent_kind.get(e, 'financial_figure')
        for t in target_times:
            val = inp_by_ent[e].get(t)
            if val is None:
                for o in hist:
                    if o['entities'][0] == e and o['time'] == t:
                        val = o['value']; break
            if val is None:
                data = sorted([(o['time'], o['value']) for o in hist if o['entities'][0] == e and o['time'] is not None])
                if len(data) >= 2:
                    try:
                        ts, vs = zip(*data)
                        poly = np.poly1d(np.polyfit(ts, vs, 1))
                        val = float(poly(t)) if t is not None else 0.0
                    except:
                        val = data[-1][1] if data else 0.0
                elif len(data) == 1:
                    val = data[0][1]
                else:
                    val = 0.0

            src = [[None, 0, [None, None]]]
            for inp in inputs:
                if e in inp['entities'] and inp['time'] == t:
                    src = inp.get('src', src); break
            if src == [[None, 0, [None, None]]]:
                for o in hist:
                    if o['entities'][0] == e and o['time'] == t:
                        src = o['src']; break

            res.append({"time": t, "kind": kind, "entities": [e], "value": val, "src": src})
    return res

