        for e in inp.get('entities', []):
            inp_map.setdefault(e, {})[t] = val

    hist_map = {}
    for o in hist:
        e = o['entities'][0]
        hist_map.setdefault(e, {})[o['time']] = o['value']

    entities = list(set(list(inp_map.keys()) + list(hist_map.keys())))
    if not entities: return []

    all_times = set()
    for n in scope_nodes(doc, scope):
        if n.get('kind') == 'table' and n.get('table', {}).get('columns'):
            cols = n['table']['columns']
            if len(cols) > 1:
                for c in cols[1:]:
                    t = _get_time(c)
                    all_times.add(t)
    for e in entities:
        if e in inp_map: all_times.update(inp_map[e].keys())
        if e in hist_map: all_times.update(hist_map[e].keys())

    num_times = sorted([t for t in all_times if t is not None])
    if None in all_times: num_times.insert(0, None)

    if start is not None: num_times = [t for t in num_times if t > start]
    if horizon is not None: num_times = [t for t in num_times if t <= horizon]
    target_times = num_times
    if not target_times: return []

    is_sum = {}
    check_times = sorted([t for t in all_times if t is not None])
    for e in entities:
        if not check_times: break
        for t in check_times:
            vals = {o['entities'][0]: o['value'] for o in hist if o['time'] == t and o['value'] is not None}
            if e not in vals: continue
            v = vals[e]
            others = [vals[x] for x in vals if x != e]
            if others and abs(sum(others) - v) / max(abs(v), 1e-9) < 0.05:
                is_sum[e] = True
                break

    def get_val(e, t):
        if e in inp_map and t in inp_map[e]: return inp_map[e][t]
        if e in hist_map and t in hist_map[e]: return hist_map[e][t]
        if is_sum.get(e):
            s = 0.0
            found = False
            for c in entities:
                if c == e: continue
                v = get_val(c, t)
                if v is not None: s += v; found = True
            return s if found else None
        if e in hist_map:
            vals = sorted(hist_map[e].items())
            return vals[-1][1] if vals else 0.0
        return 0.0

    res = []
    for e in entities:
        kind = 'financial_figure'
        for o in hist:
            if o['entities'][0] == e: kind = o['kind']; break

        for t in target_times:
            val = get_val(e, t)
            if val is None: continue

            cur_kind = kind
            src = [[None, 0, [None, None]]]

            for inp in inputs:
                if e in inp.get('entities', []) and inp['time'] == t:
                    cur_kind = inp.get('kind', kind)
                    src = inp.get('src', src)
                    break
            if src == [[None, 0, [None, None]]]:
                for o in hist:
                    if o['entities'][0] == e and o['time'] == t:
                        src = o['src']
                        cur_kind = o['kind']
                        break

            res.append({"time": t, "kind": cur_kind, "entities": [e], "value": val, "src": src})
    return res

