                vals[e] = inp_map[(e, t)]
            elif e in hist:
                vals[e] = hist[e]
            else:
                vals[e] = 0.0

        # Compute total entities as sum of components
        for e in total_ents:
            vals[e] = sum(vals.get(c, 0.0) for c in all_ents if c not in total_ents)

        # Record outcomes
        for e in all_ents:
            if e not in vals: continue
            results.append({
                "time": t,
                "kind": inp_kinds.get(e, hist_kinds.get(e, 'financial_figure')),
                "entities": [e],
                "value": round(vals[e], 2),
                "src": []
            })
    return results

import re

def _parse_num(s):
    if s is None: return None
    s = str(s).strip()
    if s in ('', '—', '-', '–', 'None', 'n/a', 'N/A', 'col0', 'Note'): return None
    neg = False
    if s.startswith('(') and s.endswith(')'):
        neg = True
        s = s[1:-1]
    s = re.sub(r'[^\d.\-]', '', s)
    if not s or s == '-': return None
    try:
        v = float(s)
        return -v if neg else v
    except ValueError:
        return None

def _get_time(col_str):
    if not col_str: return None
    s = str(col_str)
    m = re.search(r'\b((?:19|20)\d{2})\b', s)
    if m: return float(m.group(1))
    m = re.search(r'\b[Ff](\d{2})\b', s)
    if m: return float(2000 + int(m.group(1)))
    return None

def _is_section_header(rd, label_col):
    val = (rd.get(label_col) or '').strip()
    if not val: return True
    vl = val.lower()
    if vl.startswith('(') or vl.startswith('note') or 'in ' in vl[:5] or 'year' in vl or 'fiscal' in vl or 'quarter' in vl or 'period' in vl:
        return True
    if re.match(r'^\s*\(\$?|\(in|\(dollars|\(m|\(£|\(€|\(nt|\(millions|\(thousands', vl):
        return True
    return False

def entities(doc, scope):
    nodes = scope_nodes(doc, scope)
    ent_set = set()
    for n in nodes:
        if n.get('kind') == 'table':
            cols = n['table']['columns']
            if not cols: continue
            label_col = cols[0]
            for idx, rd in table_rows(n):
                name = (rd.get(label_col) or '').strip()
                if not name: continue
                if _is_section_header(rd, label_col): continue
                ent_set.add(name)
    return [{"id": e, "description": e} for e in sorted(ent_set)]

def recorded_end(doc, scope):
    nodes = scope_nodes(doc, scope)
    max_t = None
    for n in nodes:
        if n.get('kind') == 'table':
            for c in n['table']['columns']:
                t = _get_time(c)
                if t is not None and (max_t is None or t > max_t):
                    max_t = t
        elif n.get('kind') in ('list', 'text'):
            lines = n.get('lines') or [n.get('text', '')]
            for line in lines:
                t = _get_time(line)
                if t is not None and (max_t is None or t > max_t):
                    max_t = t
    return max_t

def inputs(doc, scope):
    return []

def outcomes(doc, scope):
    nodes = scope_nodes(doc, scope)
    outs = []
    for n in nodes:
        if n.get('kind') == 'table':
            cols = n['table']['columns']
            if not cols: continue
            label_col = cols[0]
            for idx, rd in table_rows(n):
                name = (rd.get(label_col) or '').strip()
                if not name or _is_section_header(rd, label_col): continue

                for col in cols:
                    if col == label_col: continue
                    t = _get_time(col)
                    val = _parse_num(rd.get(col, ''))
                    if val is not None:
                        kind = "percentage" if "%" in (col + (rd.get(col,''))) else "financial_figure"
                        outs.append({
                            "time": t,
                            "kind": kind,
                            "entities": [name],
                            "value": val,
                            "src": [[n['node_id'], idx, [label_col, col]]]
                        })
    return outs

def params(doc, scope):
    return {}


# ---- step 2: forward model ----
def simulate(doc, scope, inputs, params, start=None, horizon=None):
    rec_end = recorded_end(doc, scope)
    if start is None: start = rec_end
    if horizon is None: horizon = rec_end
    if start is None or horizon is None: return []

    # Extract entities and values from inputs
    all_ents = []
    seen_ents = set()
    inp_map = {}       # (entity, time) -> value
    inp_kinds = {}     # entity -> kind
    inp_times = set()

    for inp in inputs:
        if not isinstance(inp, dict): continue
        ents = inp.get('entities', [])
        for e in ents:
            if e not in seen_ents:
                all_ents.append(e)
                seen_ents.add(e)
            inp_kinds.setdefault(e, inp.get('kind', 'financial_figure'))

        t = inp.get('time')
        v = inp.get('value')
        if v is not None and t is not None:
            tf = float(t)
            for e in ents:
                inp_map[(e, tf)] = v
                inp_times.add(tf)
        elif v is not None and t is None:
            for e in ents:
                inp_map[(e, None)] = v

    # Fallback to doc entities if inputs don't specify them
    if not all_ents:
        scope_ents = entities(doc, scope)
        all_ents = [e['id'] for e in scope_ents]

    if not all_ents: return []

    # Determine simulation time points
    range_times = set(float(y) for y in range(int(start) + 1, int(horizon) + 1))
    sim_times = sorted([t for t in (inp_times | range_times) if t > start and t <= horizon])
    if not sim_times: return []

    # Historical state at or before start (from document)
    hist_vals = {}
    hist_kinds = {}
    for o in outcomes(doc, scope):
        t = o.get('time')
        if t is not None and t <= start:
            for e in o['entities']:
                hist_vals[e] = o['value']
                hist_kinds.setdefault(e, o.get('kind', 'financial_figure'))

    total_ents = {e for e in all_ents if 'total' in e.lower()}
    results = []

    for t in sim_times:
        vals = {}
        # 1. Compute non-total entities
        for e in all_ents:
            if e in total_ents: continue

            # Priority 1: Exact input match
            if (e, t) in inp_map:
                vals[e] = inp_map[(e, t)]
                continue

            # Priority 2: Carry forward latest input <= t
            latest_inp = None
            for (ent, tt), vv in inp_map.items():
                if ent == e and tt is not None and tt <= t:
                    if latest_inp is None or tt > latest_inp[0]:
                        latest_inp = (tt, vv)
            if latest_inp is not None:
                vals[e] = latest_inp[1]
                continue

            # Priority 3: Historical carry-forward
            if e in hist_vals:
                vals[e] = hist_vals[e]
                continue

            vals[e] = 0.0

        # 2. Compute total entities as sum of components
        for e in total_ents:
            vals[e] = sum(vals.get(c, 0.0) for c in all_ents if c not in total_ents)

        # 3. Record outcomes
        for e in all_ents:
            if e not in vals: continue
            kind = inp_kinds.get(e, hist_kinds.get(e, 'financial_figure'))
            results.append({
                "time": t,
                "kind": kind,
                "entities": [e],
                "value": round(vals[e], 2),
                "src": []
            })
    return results

