# ---- step 2: forward model ----
def simulate(doc, scope, inputs, params, start=None, horizon=None):
    # Collect all entities and their metadata strictly from inputs
    all_ents = []
    seen = set()
    kinds = {}
    records = []  # (time, entity, value)

    for rec in inputs:
        if not isinstance(rec, dict): continue
        ents = rec.get('entities', [])
        if not ents: continue
        for e in ents:
            if e not in seen:
                all_ents.append(e)
                seen.add(e)
            kinds[e] = rec.get('kind', 'financial_figure')

        t = rec.get('time')
        v = rec.get('value')
        if v is not None:
            for e in ents:
                records.append((t, e, v))

    if not all_ents:
        return []

    # Determine simulation time points
    if horizon is None:
        times = sorted(list(set(float(t) for t, _, _ in records if t is not None and t > start)))
    else:
        if start is None: start = 0.0
        range_t = [float(y) for y in range(int(start) + 1, int(horizon) + 1)]
        inp_t = set(float(t) for t, _, _ in records if t is not None)
        times = sorted([t for t in set(range_t) | inp_t if t > start and t <= horizon])

    if not times:
        return []

    # Build historical state at or before start
    hist = {}
    for t, e, v in records:
        if t is None: continue
        if t <= start:
            hist[e] = v

    total_ents = {e for e in all_ents if 'total' in e.lower()}
    results = []

    for t in times:
        vals = {}
        # Non-total entities: carry forward latest known value <= t
        for e in all_ents:
            if e in total_ents: continue

            latest = None
            for tt, ee, vv in records:
                if ee == e and tt is not None and tt <= t:
                    if latest is None or tt > latest[0]:
                        latest = (tt, vv)

            vals[e] = latest[1] if latest else 0.0

        # Total entities: sum of components
        for e in total_ents:
            vals[e] = sum(vals.get(c, 0.0) for c in all_ents if c not in total_ents)

        # Record outcomes
        for e in all_ents:
            if e not in vals: continue
            results.append({
                "time": t,
                "kind": kinds.get(e, 'financial_figure'),
                "entities": [e],
                "value": round(vals[e], 2),
                "src": []
            })
    return results
